using EduCenterManagement.Constants;using EduCenterManagement.Repositories;using EduCenterManagement.Services.Common;using EduCenterManagement.ViewModels.TeacherComment;
namespace EduCenterManagement.Services;
public sealed class TeacherCommentService(ICurrentUserContext current,ITeacherCommentRepository repo,INotificationService notifications,ILogger<TeacherCommentService> logger):ITeacherCommentService { async Task<int?> Teacher(CancellationToken ct)=>await current.GetTeacherProfileIdAsync(ct);public async Task<IReadOnlyList<TeacherClassViewModel>?> GetClassesAsync(CancellationToken ct=default)=>await Teacher(ct) is int t?await repo.GetClassesAsync(t,ct):null;public async Task<IReadOnlyList<TeacherStudentViewModel>?> GetStudentsAsync(int c,CancellationToken ct=default)=>await Teacher(ct) is int t?await repo.GetStudentsAsync(t,c,ct):null;public async Task<TeacherCommentFormViewModel?> GetFormAsync(int c,int s,int? id,CancellationToken ct=default)=>await Teacher(ct) is int t?await repo.GetFormAsync(t,c,s,id,ct):null;public async Task<int?> CreateAsync(TeacherCommentFormViewModel f,CancellationToken ct=default){if(await Teacher(ct) is not int t)return null;var id=await repo.CreateAsync(t,f,ct);if(id is not int commentId)return null;try{var data=await repo.GetNotificationDataAsync(commentId,ct);if(data is not null){var message=$"Teacher {data.Value.Teacher} left a comment for {data.Value.Student} in {data.Value.ClassName}.";await notifications.CreateForParentsOfStudentAsync(f.StudentId,NotificationTypes.TeacherComment,"New teacher comment",message,"TeacherComment",commentId,ct);await notifications.CreateAsync(data.Value.StudentUserId,NotificationTypes.TeacherComment,"New teacher comment",message,"TeacherComment",commentId,f.StudentId,ct);}}catch(Exception ex){logger.LogError(ex,"Comment {CommentId} saved but notifications failed.",commentId);}return id;}public async Task<bool> UpdateAsync(TeacherCommentFormViewModel f,CancellationToken ct=default)=>await Teacher(ct) is int t&&await repo.UpdateAsync(t,f,ct);public async Task<bool> DeleteAsync(int id,CancellationToken ct=default)=>await Teacher(ct) is int t&&await repo.DeleteAsync(t,id,ct);public async Task<IReadOnlyList<TeacherCommentHistoryItemViewModel>?> GetHistoryAsync(int c,int s,CancellationToken ct=default)=>await Teacher(ct) is int t?await repo.GetHistoryAsync(t,c,s,ct):null;}
